{
  "verdict": "not_met",
  "evidence": "The 'Receipt' and 'Mileage' buttons are positioned directly over the 'Recent activity' list, partially obscuring the activity details such as 'Date: 2026-10-24' and 'Category: Supplies'."
}

{
  "verdict": "not_met",
  "evidence": "The Recent activity list shows a row with 'Receipt saved', 'Date', 'Category', and 'Office supplies', but no amount is displayed for this activity row."
}

{
  "verdict": "met",
  "evidence": "The 'Recent activity' list is scrollable, as evidenced by the visible scrollable content (e.g., 'Receipt saved' entry) and the presence of 'Receipt' and 'Mileage' buttons below it. The buttons are not currently visible at the top of the list, suggesting they can be scrolled out of view."
}

{
  "verdict": "met",
  "evidence": "The spacing between input fields (Amount, Date, Category, Type, Notes) is consistent and there are no empty gaps larger than the standard spacing between input fields."
}

{
  "verdict": "met",
  "evidence": "The \"Scan receipt\" button is present but appears disabled (greyed out), which indicates it is hidden from use when scanning functionality is unavailable, meeting the requirement."
}

{
  "verdict": "met",
  "evidence": "The App lock option appears as a switch row at the top of the Settings screen, with a toggle switch. There is no separate App lock button visible below it."
}

{
  "verdict": "not_met",
  "evidence": "The 'Tax settings', 'Categories', 'Export', 'Backup & restore', and 'View Terms and Privacy Policy' entries are displayed as outlined buttons, not as list rows with a chevron."
}

{
  "verdict": "not_met",
  "evidence": "The 'Delete all data' entry is not displayed in an error color; it appears in the same blue text color as the other settings options."
}

